class MyCircularDeque {
    private int[] data;
    private int front, rear, cap;
    public MyCircularDeque(int k) {
        cap = k + 1; data = new int[cap]; front = 0; rear = 0;
    }
    public boolean insertFront(int value) {
        if (isFull()) return false;
        front = (front - 1 + cap) % cap;
        data[front] = value;
        return true;
    }
    public boolean insertLast(int value) {
        if (isFull()) return false;
        data[rear] = value;
        rear = (rear + 1) % cap;
        return true;
    }
    public boolean deleteFront() {
        if (isEmpty()) return false;
        front = (front + 1) % cap;
        return true;
    }
    public boolean deleteLast() {
        if (isEmpty()) return false;
        rear = (rear - 1 + cap) % cap;
        return true;
    }
    public int getFront() { return isEmpty() ? -1 : data[front]; }
    public int getRear() { return isEmpty() ? -1 : data[(rear - 1 + cap) % cap]; }
    public boolean isEmpty() { return front == rear; }
    public boolean isFull() { return (rear + 1) % cap == front; }
}

class MyCircularDeque {
    private int[] vals, prevs, nexts;
    private int headSentinel, tailSentinel, size, cap, cnt;
    public MyCircularDeque(int k) {
        cap = k;
        vals = new int[k + 4];
        prevs = new int[k + 4];
        nexts = new int[k + 4];
        headSentinel = 0; tailSentinel = 1; cnt = 2; size = 0;
        nexts[headSentinel] = tailSentinel;
        prevs[tailSentinel] = headSentinel;
    }
    public boolean insertFront(int value) {
        if (isFull()) return false;
        int node = cnt++;
        vals[node] = value;
        int after = nexts[headSentinel];
        nexts[headSentinel] = node; prevs[node] = headSentinel;
        nexts[node] = after; prevs[after] = node;
        size++;
        return true;
    }
    public boolean insertLast(int value) {
        if (isFull()) return false;
        int node = cnt++;
        vals[node] = value;
        int before = prevs[tailSentinel];
        nexts[before] = node; prevs[node] = before;
        nexts[node] = tailSentinel; prevs[tailSentinel] = node;
        size++;
        return true;
    }
    public boolean deleteFront() {
        if (isEmpty()) return false;
        int del = nexts[headSentinel];
        int after = nexts[del];
        nexts[headSentinel] = after; prevs[after] = headSentinel;
        size--;
        return true;
    }
    public boolean deleteLast() {
        if (isEmpty()) return false;
        int del = prevs[tailSentinel];
        int before = prevs[del];
        nexts[before] = tailSentinel; prevs[tailSentinel] = before;
        size--;
        return true;
    }
    public int getFront() { return isEmpty() ? -1 : vals[nexts[headSentinel]]; }
    public int getRear() { return isEmpty() ? -1 : vals[prevs[tailSentinel]]; }
    public boolean isEmpty() { return size == 0; }
    public boolean isFull() { return size == cap; }
}
